func split(ctx context.Context, m Order, out Publisher) error {
    for i, item := range m.Items {
        p := Part{Corr: m.ID, Seq: i, Size: len(m.Items), Item: item}
        if err := out.Publish(ctx, p); err != nil {
            return fmt.Errorf("part %d of %s: %w", i, m.ID, err)
        }
    }
    return nil
}

